def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def safe_pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            x, y = v[0], v[1]
            if isinstance(x, (int, float)) and isinstance(y, (int, float)):
                return int(x), int(y)
        return default

    def best_by(items, score_fn):
        best_item = None
        best_score = None
        for item in items or []:
            try:
                s = score_fn(item)
            except Exception:
                continue
            if best_item is None or s < best_score:
                best_item = item
                best_score = s
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position"))
    ox, oy = safe_pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "evader":
            corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
            target = best_by(corners, lambda p: -(abs(p[0] - ox) + abs(p[1] - oy)))
            if target is None:
                return [sign(sx - ox), sign(sy - oy)]
            return [sign(target[0] - sx), sign(target[1] - sy)]
        return [sign(ox - sx), sign(oy - sy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = best_by(targets, lambda p: abs(p[0] - sx) + abs(p[1] - sy))
        if target is None:
            center = (gw // 2, gh // 2) if gw and gh else (sx, sy)
            return [sign(center[0] - sx), sign(center[1] - sy)]
        return [sign(target[0] - sx), sign(target[1] - sy)]

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("targets") or []
    target = best_by(resources, lambda p: abs(p[0] - sx) + abs(p[1] - sy))
    if target is not None:
        dx = sign(target[0] - sx)
        dy = sign(target[1] - sy)
        if abs(ox - sx) + abs(oy - sy) <= 2:
            dx += sign(sx - ox)
            dy += sign(sy - oy)
        return [sign(dx), sign(dy)]

    # Fallback: move away from opponent, otherwise stay put.
    return [sign(sx - ox), sign(sy - oy)]

